-- Timeout/crash regression sample: thousands of sequential loop-carried while loops.
--
-- Each loop merges the carried register through its header phi, linking every SSA
-- version forward into one union-find chain tens of thousands long. Before the fix,
-- `ASTLifterFunctionState::VariableOf` recursed once per parent link and overflowed
-- the native stack (~13k loops, exit 0xC00000FD) when debug-local resolution read the
-- oldest versions first (--debug 2 only). Now iterative with path compression.
-- Decompiles successfully in ~60s (quadratic pre-passes); seqwhile_32k.lua exceeds the
-- 120s decompile budget and fails gracefully with FailedToDecompile instead.
local s = 0
while s < 1 do s = s + 1 end
while s < 2 do s = s + 1 end
while s < 3 do s = s + 1 end
while s < 4 do s = s + 1 end
while s < 5 do s = s + 1 end
